// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 value, bool makeRecipientRevert) public {
        value = bound(value, 1, 1 ether);

        AttackerPayable attacker = new AttackerPayable(makeRecipientRevert);

        vm.deal(address(this), value);
        payable(address(c)).transfer(value);

        uint256 before = address(c).balance;
        assert(before == value);

        _shouldRevertOnReceive = makeRecipientRevert;

        bool ok;
        try c.withdraw{value:0}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == before);
        }
    }

    bool _shouldRevertOnReceive;

    receive() external payable {
        if (_shouldRevertOnReceive) revert("receive revert");
    }
}

contract AttackerPayable {
    bool public willRevert;
    constructor(bool _r) payable { willRevert = _r; }
    receive() external payable {
        if (willRevert) revert("bad");
    }
}
